// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue, uniqueSuffix } from '@skyramp/skyramp';
import { createCoupon, getCoupon, deleteCoupon } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    const couponsPostResponse = await createCoupon(
        client,
        headers,
        uniqueSuffix("TESTBOT-ID-BASE"),
        10,
        201
    );
    expect(couponsPostResponse.statusCode, 'status code').toBe(201);

    expect(getResponseValue(couponsPostResponse, "response.discountPercent"), 'discountPercent').toBe(10);
    expect(getResponseValue(couponsPostResponse, "response.id"), 'id').toBeGreaterThan(0);

    const createdCouponId = getResponseValue(couponsPostResponse, "response.id");
    const createdCouponCode = getResponseValue(couponsPostResponse, "response.code");

    // The owned coupon reads back — the accepted request the rejections below are measured against.
    const couponsCouponsGetResponse = await getCoupon(client, headers, createdCouponId, 200);
    expect(couponsCouponsGetResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(couponsCouponsGetResponse, "response.id"), 'id').toBe(createdCouponId);
    expect(getResponseValue(couponsCouponsGetResponse, "response.code"), 'code').toBe(createdCouponCode);
    expect(getResponseValue(couponsCouponsGetResponse, "response.discountPercent"), 'discountPercent').toBe(10);

    // An id that does not exist.
    const coupons999999999GetResponse = await getCoupon(client, headers, "999999999", 404);
    expect(coupons999999999GetResponse.statusCode, 'status code').toBe(404);
    expect(getResponseValue(coupons999999999GetResponse, "response"), 'error message').toBe("Coupon not found.");
    expect(getResponseValue(coupons999999999GetResponse, "response.id"), 'no coupon is returned').toBeNull();

    // A non-numeric id.
    const abcGetResponse = await getCoupon(client, headers, "abc", 400);
    expect(abcGetResponse.statusCode, 'status code').toBe(400);
    expect(getResponseValue(abcGetResponse, "response"), 'error message').toBe("Invalid coupon ID.");
    expect(getResponseValue(abcGetResponse, "response.id"), 'no coupon is returned').toBeNull();

    // A fractional id: the Int column cannot match it, so it must be refused as
    // client input rather than reaching the query and crashing the handler.
    const coupons15GetResponse = await getCoupon(client, headers, "1.5", 400);
    expect(coupons15GetResponse.statusCode, 'status code').toBe(400);
    expect(getResponseValue(coupons15GetResponse, "response"), 'error message').toBe("Invalid coupon ID.");
    expect(getResponseValue(coupons15GetResponse, "response.id"), 'no coupon is returned').toBeNull();

    // A method the route does not implement.
    const couponsCouponsDeleteResponse = await deleteCoupon(client, headers, createdCouponId, 405);
    expect(couponsCouponsDeleteResponse.statusCode, 'status code').toBe(405);
    expect(getResponseValue(couponsCouponsDeleteResponse, "response"), 'error message').toBe("Method not allowed.");

    // The refused DELETE must leave the coupon exactly as it was.
    const couponsAfterDeleteGetResponse = await getCoupon(client, headers, createdCouponId, 200);
    expect(getResponseValue(couponsAfterDeleteGetResponse, "response.id"), 'coupon survives the refused DELETE').toBe(createdCouponId);
    expect(getResponseValue(couponsAfterDeleteGetResponse, "response.discountPercent"), 'discountPercent is unchanged').toBe(10);
});
